1	// Differential harness: run the frozen Python executable and the Node port on
2	// the same argv and report any divergence.
3	//
4	// Usage:
5	//   node /tmp/harness/diff.mjs '<json-array-of-argv>'          # one case
6	//   node /tmp/harness/diff.mjs --file cases.json               # many cases
7	//
8	// cases.json is a JSON array whose entries are either argv arrays or
9	// {name, argv} objects. Exit status is 1 if any case diverged.
10	//
11	// Argv entries may use \uXXXX escapes to carry arbitrary characters. A NUL
12	// byte cannot survive execve(), so such cases are skipped.
13	
14	import { spawnSync } from 'node:child_process';
15	import { readFileSync } from 'node:fs';
16	
17	const PY = '/workspace/dataset/test6_executable';
18	const JS = '/output/test6.mjs';
19	
20	// The PyInstaller banner embeds the pid, which necessarily differs run to run.
21	function normalise(text) {
22	  return text.replace(/\[PYI-\d+:/g, '[PYI-N:');
23	}
24	
25	function run(command, argv) {
26	  const result = spawnSync(command[0], [...command.slice(1), ...argv], {
27	    encoding: 'utf8',
28	    maxBuffer: 64 * 1024 * 1024,
29	  });
30	  return {
31	    status: result.status,
32	    stdout: result.stdout ?? '',
33	    stderr: normalise(result.stderr ?? ''),
34	  };
35	}
36	
37	function hasNul(token) {
38	  for (let i = 0; i < token.length; i += 1) {
39	    if (token.charCodeAt(i) === 0) return true;
40	  }
41	  return false;
42	}
43	
44	function describe(argv) {
45	  return argv.map((token) => JSON.stringify(token)).join(' ');
46	}
47	
48	const [first, second] = process.argv.slice(2);
49	const cases =
50	  first === '--file' ? JSON.parse(readFileSync(second, 'utf8')) : [JSON.parse(first)];
51	
52	let failures = 0;
53	let skipped = 0;
54	for (const entry of cases) {
55	  const argv = Array.isArray(entry) ? entry : entry.argv;
56	  const name = Array.isArray(entry) ? describe(argv) : entry.name;
57	  if (argv.some(hasNul)) {
58	    skipped += 1;
59	    console.log(`SKIP  ${name}  (NUL cannot pass through execve)`);
60	    continue;
61	  }
62	  const py = run([PY], argv);
63	  const js = run(['node', JS], argv);
64	  if (py.status === js.status && py.stdout === js.stdout && py.stderr === js.stderr) continue;
65	  failures += 1;
66	  console.log(`FAIL  ${name}`);
67	  console.log(`  argv: ${describe(argv)}`);
68	  console.log(`  py  rc=${py.status} out=${JSON.stringify(py.stdout)} err=${JSON.stringify(py.stderr)}`);
69	  console.log(`  js  rc=${js.status} out=${JSON.stringify(js.stdout)} err=${JSON.stringify(js.stderr)}`);
70	}
71	console.log(`\n${cases.length - failures - skipped}/${cases.length} matched, ${failures} failed, ${skipped} skipped`);
72	process.exit(failures > 0 ? 1 : 0);
73

1	// Port of test6.py: bencode a nested list built from the command line, then
2	// decode it back and print both forms.
3	
4	import { ArgumentParser, ArgumentError, ArgumentParserError, STR, INT } from './lib/argparse/index.mjs';
5	import * as bencoder from './lib/bencode/index.mjs';
6	import { encodeAscii } from './lib/python/codecs.mjs';
7	import { PythonError, SystemExit } from './lib/python/errors.mjs';
8	import { pyRepr } from './lib/python/repr.mjs';
9	import { reportUnhandled } from './lib/python/traceback.mjs';
10	import { printLine, exitWith, scriptArgs } from './lib/python/sys.mjs';
11	
12	// The frozen executable reports itself under this name in usage and errors.
13	const PROG = 'test6_executable';
14	const SOURCE_FILE = 'test6.py';
15	const SCRIPT_NAME = 'test6';
16	
17	// The line the encode() call sits on in the original source, quoted by the
18	// traceback when --a carries a non-ASCII character.
19	const ENCODE_LINE = 9;
20	
21	function buildParser() {
22	  const parser = new ArgumentParser({ prog: PROG });
23	  parser.addArgument('--a', { type: STR, required: true });
24	  parser.addArgument('--b', { type: INT, required: true });
25	  return parser;
26	}
27	
28	function main() {
29	  const parser = buildParser();
30	  let args;
31	  try {
32	    args = parser.parseArgs(scriptArgs());
33	  } catch (error) {
34	    // argparse funnels both failure kinds through parser.error(), which prints
35	    // usage and exits 2.
36	    if (error instanceof ArgumentError || error instanceof ArgumentParserError) {
37	      parser.error(error.message);
38	    }
39	    throw error;
40	  }
41	
42	  const listData = [encodeAscii(args.a), args.b, [args.b]];
43	  const encoded = bencoder.encode(listData);
44	  const decoded = bencoder.decode(encoded);
45	  printLine(pyRepr(encoded));
46	  printLine(pyRepr(decoded));
47	}
48	
49	try {
50	  main();
51	} catch (error) {
52	  if (error instanceof SystemExit) {
53	    exitWith(error.code);
54	  } else if (error instanceof PythonError) {
55	    reportUnhandled(error, {
56	      fileName: SOURCE_FILE,
57	      lineNumber: ENCODE_LINE,
58	      scriptName: SCRIPT_NAME,
59	    });
60	    exitWith(1);
61	  } else {
62	    throw error;
63	  }
64	}
