1	// Python's repr() for the value shapes this program prints.
2	
3	import { PyBytes } from './bytes.mjs';
4	import { isPrintable } from '../unicode/properties.mjs';
5	
6	// repr prefers single quotes, switching to double only when that avoids
7	// escaping — i.e. when the value contains ' but no ".
8	function pickQuote(hasSingle, hasDouble) {
9	  return hasSingle && !hasDouble ? '"' : "'";
10	}
11	
12	// The only mnemonic escapes repr emits. Notably \v, \f, \a and \b are *not*
13	// among them; those fall through to \xHH.
14	const MNEMONIC_ESCAPES = new Map([
15	  [0x5c, '\\\\'],
16	  [0x09, '\\t'],
17	  [0x0a, '\\n'],
18	  [0x0d, '\\r'],
19	]);
20	
21	function hexEscape(codePoint) {
22	  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
23	  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
24	  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
25	}
26	
27	export function reprBytes(value) {
28	  const { codes } = value;
29	  const quote = pickQuote(codes.includes(0x27), codes.includes(0x22));
30	  const quoteCode = quote.charCodeAt(0);
31	  let out = `b${quote}`;
32	  for (const code of codes) {
33	    const mnemonic = MNEMONIC_ESCAPES.get(code);
34	    if (mnemonic !== undefined) out += mnemonic;
35	    else if (code === quoteCode) out += `\\${quote}`;
36	    else if (code < 0x20 || code >= 0x7f) out += hexEscape(code);
37	    else out += String.fromCharCode(code);
38	  }
39	  return out + quote;
40	}
41	
42	export function reprStr(text) {
43	  const quote = pickQuote(text.includes("'"), text.includes('"'));
44	  let out = quote;
45	  for (const ch of text) {
46	    const codePoint = ch.codePointAt(0);
47	    const mnemonic = MNEMONIC_ESCAPES.get(codePoint);
48	    if (mnemonic !== undefined) out += mnemonic;
49	    else if (ch === quote) out += `\\${quote}`;
50	    else if (!isPrintable(ch)) out += hexEscape(codePoint);
51	    else out += ch;
52	  }
53	  return out + quote;
54	}
55	
56	export function reprInt(value) {
57	  return String(value);
58	}
59	
60	// Containers delegate to repr for their members, exactly as Python does.
61	export function pyRepr(value) {
62	  if (value instanceof PyBytes) return reprBytes(value);
63	  if (typeof value === 'bigint') return reprInt(value);
64	  if (typeof value === 'string') return reprStr(value);
65	  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
66	  if (value instanceof Map) {
67	    const entries = [];
68	    for (const [key, item] of value) entries.push(`${pyRepr(key)}: ${pyRepr(item)}`);
69	    return `{${entries.join(', ')}}`;
70	  }
71	  if (value === null) return 'None';
72	  if (value === true) return 'True';
73	  if (value === false) return 'False';
74	  return String(value);
75	}
